// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1) Apanha clientes (do Webhook) e investimentos (do Code do CSV)
let clientes = [];
let investimentos = [];

for (const item of $input.all()) {
  const j = item.json;
  if (j.body?.clientes) clientes = j.body.clientes;
  if (j.investimentos) investimentos = j.investimentos;
}

// 2) Funções auxiliares
const saldoParaNumero = (txt) =>
  Number(String(txt).replace(/[^\d,]/g, "").replace(",", ".")) || 0;

const pick = (lista) => lista[Math.floor(Math.random() * lista.length)];

// 3) Para cada cliente, escolhe um investimento e gera mensagens
const resultados = clientes.map(c => {
  const saldoNum = saldoParaNumero(c.saldo);

  const doPerfil = investimentos.filter(i => i.perfil === c.perfil);
  const acessiveis = doPerfil.filter(i => i.minimo <= saldoNum);

  let escolhido = null;
  let motivo = "";

  if (acessiveis.length > 0) {
    // o mais ambicioso que o saldo permite
    escolhido = acessiveis.sort((a, b) => b.minimo - a.minimo)[0];
    motivo = `Compatível com o perfil ${c.perfil} e com o saldo disponível.`;
  } else if (doPerfil.length > 0) {
    // saldo abaixo de todos os mínimos: sugere o de entrada mais baixa
    escolhido = doPerfil.sort((a, b) => a.minimo - b.minimo)[0];
    motivo = `Saldo abaixo do mínimo; esta é a opção de entrada mais baixa do perfil.`;
  }

  const nomeProduto = escolhido ? escolhido.produto : "uma opção do seu perfil";
  const rent = escolhido ? escolhido.rentabilidade : "";

  const mensagens = [
    `Olá, ${c.nome}! Com o seu perfil ${c.perfil}, sugerimos ${nomeProduto} (${rent}).`,
    `${c.nome}, temos uma recomendação para si: ${nomeProduto}, alinhada com o seu perfil ${c.perfil}.`,
    `Bom dia, ${c.nome}! Analisámos o seu perfil ${c.perfil} e ${nomeProduto} pode ser uma boa opção.`
  ];

  return {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacoes: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.-]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacoes: c.recomendacoes,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

