const emails = $('Code in JavaScript2').all(); // dados do cliente (um item por cliente)
const out = [];

$input.all().forEach((item, i) => {
  const j = item.json;
  const base = emails[i]?.json ?? {};

  // 1) Texto que o modelo devolveu
  const raw =
    j.output?.[0]?.content?.[0]?.text ??   // formato OpenAI
    j.content?.parts?.[0]?.text ??         // formato Gemini
    j.text ?? "";

  // 2) Tira cercas de markdown e converte em JSON
  const limpo = String(raw).replace(/```json|```/g, "").trim();
  let mail = {};
  try { mail = JSON.parse(limpo); } catch (e) { mail = {}; }

  // 3) Se o modelo falhar, usa a mensagem-base como alternativa
  const subject = mail.subject || "Sugestão de investimento";
  const text_body = mail.text_body || base.mensagem_base || "";
  const html_body = mail.html_body || `<p>${text_body}</p>`;

  out.push({
    json: {
      ok: !!mail.subject,
      to: base.email_to,
      subject,
      text_body,
      html_body,

      // opcional: campos úteis para debug/auditoria
      meta: {
        nome: base.nome,
        perfil: base.perfil,
        produto: base.recomendacoes?.produto,
        minimo: base.recomendacoes?.minimo,
        rentabilidade: base.recomendacoes?.rentabilidade,
        motivo: base.motivo
      }
    }
  });
});

return out;
